    const brandHits = BRANDS.filter(b => host.includes(b) && host !== `${b}.com` && !host.endsWith(`.${b}.com`) && !host.endsWith(`.${b}.co.uk`));
    if (brandHits.length) add('brand-lookalike','Brand term in non-canonical hostname',`Brand-like token(s): ${brandHits.join(', ')}. Verify the actual registered domain; this can false-positive.`,18,'high');
    if (labels.length >= 5) add('subdomains','Deeply nested subdomains',`Hostname has ${labels.length} labels. Read the effective domain carefully.`,6,'low');
    if (RISKY_EXT.test(u.pathname)) add('risky-extension','Potentially executable/download extension','The path ends with a file extension sometimes associated with executable or macro-enabled content.',12,'high');
    if (u.port && !['80','443'].includes(u.port)) add('unusual-port','Non-standard web port',`The URL specifies port ${u.port}, which deserves verification; legitimate services can use custom ports.`,7,'low');
