  function decodeURIComponentSafe(s){try{return decodeURIComponent(s)}catch{return s}}
  function makeId(){return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`}
  function extractUrls(text) { const matches = String(text).match(/\b(?:https?:\/\/|www\.)[^\s<>"'`]+/gi) || []; const list=[]; for (let v of matches) { v=v.replace(/[),.;!?\]}]+$/g,''); if(v.startsWith('www.'))v='https://'+v; if(!list.includes(v))list.push(v); } return list.slice(0,100); }
