    const fromAddrs=getEmails(headers.from||''); const replyAddrs=getEmails(headers['reply-to']||''); const returnAddrs=getEmails(headers['return-path']||''); const signals=[];
    const add=(id,title,detail,points,severity='medium')=>signals.push({id,title,detail,points,severity});
    if(fromAddrs.length && replyAddrs.length && getDomain(fromAddrs[0])!==getDomain(replyAddrs[0])) add('reply-mismatch','Reply-To domain differs from From',`From domain: ${getDomain(fromAddrs[0]) || 'unknown'}; Reply-To domain: ${getDomain(replyAddrs[0]) || 'unknown'}. This mismatch may be legitimate but should be checked.`,18,'high');
    if(fromAddrs.length && returnAddrs.length && getDomain(fromAddrs[0])!==getDomain(returnAddrs[0])) add('return-mismatch','Return-Path differs from From','The envelope return path differs from the visible sender domain. Mailing platforms can create legitimate differences.',8,'medium');
    const auth=headers['authentication-results']||headers['received-spf']||'';
