    const urgencyHits=URGENCY.filter(re=>re.test(text)).length; if(urgencyHits) add('urgency','Urgency / account-pressure language',`Matched ${urgencyHits} urgency phrase pattern(s). Review the request and sender context; wording alone is not proof.`,Math.min(12,urgencyHits*4),'medium');
    if(/\b(?:password|passcode|one[- ]time code|security code|recovery phrase|seed phrase)\b/i.test(text) && /\b(?:reply|send|confirm|share|enter|provide|verify)\b/i.test(text)) add('credential-request','Possible credential or secret request','The message text appears to pair a sensitive secret with an action request. Never share passwords, OTPs, recovery phrases or session tokens by email.',18,'high');
    const riskyAttachments=[...new Set((text.match(/[^\s<>"']+\.(?:exe|scr|bat|cmd|com|pif|js|jse|vbs|vbe|wsf|wsh|hta|msi|msp|ps1|psm1|jar|iso|img|lnk|reg|dll|docm|xlsm|pptm|one)(?:\b|$)/gi)||[]).map(x=>x.replace(/[),.;]+$/,'')))]; if(riskyAttachments.length) add('risky-attachment','Potentially executable or macro-enabled attachment name',`Name(s) found in text: ${riskyAttachments.slice(0,8).join(', ')}. This is filename triage only, not malware scanning.`,22,'high');
