      const h=analyzeHtml(text); const signals=[]; const add=(id,title,detail,points,severity='medium')=>signals.push({id,title,detail,points,severity});
      if(h.passwordForms) add('password-form','Password field in HTML',`Found ${h.passwordForms} password field(s). Verify who receives submitted credentials.`,16,'high');
      if(h.externalFormActions) add('external-post','Form action points to another hostname',`Found ${h.externalFormActions} external form action(s). A legitimate payment/login flow can use external identity providers; verify ownership.`,14,'high');
      if(h.hiddenIframes) add('hidden-iframe','Hidden iframe element',`Found ${h.hiddenIframes} iframe(s) marked hidden. Inspect the destination and page context.`,13,'high'); else if(h.iframes) add('iframe','Iframe element(s) present',`Found ${h.iframes} iframe(s).`,5,'low');
