  function loadHistory(){try{const v=JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]');return Array.isArray(v)?v:[]}catch{return[]}}
  function saveHistory(list){try{localStorage.setItem(HISTORY_KEY,JSON.stringify(list.slice(0,100)))}catch{toast('Browser storage is full; export reports before clearing cases.','warning')}}
  function record(report){const h=loadHistory().filter(x=>x.id!==report.id);h.unshift({id:report.id,created_at:report.created_at,type:report.type,input:report.input||report.normalized_url||'Investigation',verdict:report.verdict,risk_score:report.risk_score,hostname:report.hostname||'',report});saveHistory(h);renderHistory();updateStats()}
  function updateStats(){const h=loadHistory();$('#stat-cases').textContent=h.length;$('#stat-high').textContent=h.filter(x=>x.verdict==='HIGH RISK').length;$('#stat-emails').textContent=h.filter(x=>x.type==='EMAIL').length;emailCases=h.filter(x=>x.type==='EMAIL').length;$('#stat-mode').textContent=getApiBase()?'HYBRID':'LOCAL';$('#stat-mode-sub').textContent=getApiBase()?'Local rules + configured API':'No remote services connected';$('#history-count').textContent=`${h.length} CASE${h.length===1?'':'S'}`}
  function renderHistory(){const h=loadHistory();const q=$('#history-filter').value.toLowerCase().trim();const items=h.filter(x=>`${x.input} ${x.verdict} ${x.type}`.toLowerCase().includes(q)); const body=$('#history-body');if(!items.length){body.innerHTML=`<tr><td colspan="6" class="empty-cell">${h.length?'No cases match this filter.':'No cases yet. Start an investigation above.'}</td></tr>`;return;}body.innerHTML=items.slice(0,50).map(item=>`<tr><td class="target-cell">${esc(item.input)}</td><td>${esc(item.type||'URL')}</td><td>${badge(item.verdict)}</td><td>${Number.isFinite(item.risk_score)?`${item.risk_score}/100`:'—'}</td><td>${formatTime(item.created_at)}</td><td><button class="case-link" data-open-case="${escAttr(item.id)}">OPEN ↗</button></td></tr>`).join('');$$('[data-open-case]',body).forEach(btn=>btn.addEventListener('click',()=>{const it=loadHistory().find(x=>x.id===btn.dataset.openCase);if(it?.report)showReport(it.report,false)}))}
  function badge(verdict){const cls=verdict==='HIGH RISK'?'high':verdict==='SUSPICIOUS'?'suspicious':verdict==='INCONCLUSIVE'?'inconclusive':'info';return `<span class="badge ${cls}">${esc(verdict||'UNKNOWN')}</span>`}
  function formatTime(v){try{return new Date(v).toLocaleString(undefined,{month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'})}catch{return '—'}}
  function formatUnix(v){const n=Number(v);return Number.isFinite(n)&&n>0?new Date(n*1000).toLocaleString():(v??'—')}
  function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function escAttr(s){return esc(s).replace(/`/g,'&#96;')}
  function showReport(r,save=true){currentReport=r;currentFilename=`phishshield-${r.type.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${r.id}`;if(save)record(r);$('#result-title').textContent=`${r.type||'CASE'} investigation report`;$('#result-subtitle').textContent=`Evidence overview · ${new Date(r.created_at||Date.now()).toLocaleString()}`;$('#results-section').hidden=false;$('#result-output').innerHTML=renderReport(r);$('#results-section').scrollIntoView({behavior:'smooth',block:'start'});updateStats()}
  function renderReport(r){const n=Number(r.risk_score);const score=Math.max(0,Math.min(100,Number.isFinite(n)?n:0));const signals=(r.signals||[]).filter(s=>s.points>0);const reportTarget=r.normalized_url||r.input||'Uploaded message';const meta=[`CASE ID: ${r.id||'LOCAL'}`,`ANALYZED: ${formatTime(r.created_at)}`,`SIGNALS: ${signals.length}`];let details='';
    if(r.email){const e=r.email;details=`<section class="report-panel"><h4>Email indicators</h4><div class="evidence-list">${evidence('From', (e.from||[]).join(', ')||'Not found')}${evidence('Reply-To',(e.reply_to||[]).join(', ')||'Not found')}${evidence('Return-Path',(e.return_path||[]).join(', ')||'Not found')}${evidence('Extracted URLs',String((e.urls||[]).length))}${evidence('Attachment names flagged',(e.risky_attachment_names||[]).join(', ')||'None detected')}${Object.entries(e.headers||{}).filter(([k])=>['subject','date','message-id','authentication-results','received-spf'].includes(k)).map(([k,v])=>evidence(k,v)).join('')}</div>${(e.urls||[]).length?`<h4 style="margin-top:18px">Extracted URL triage</h4><div class="signal-list">${(e.urls||[]).map(u=>`<div class="signal-item"><div class="signal-top"><b>${esc(u.input)}</b>${badge(u.verdict)}</div><p>${esc(u.hostname||'')} · ${Number.isFinite(u.risk_score)?u.risk_score+'/100':'Could not parse'}</p><button class="case-link" data-scan-url="${escAttr(u.input)}">ANALYZE URL ↗</button></div>`).join('')}</div>`:''}</section>`;}
    if(r.page){details+=`<section class="report-panel"><h4>Page / HTML evidence</h4><div class="evidence-list">${evidence('Document title',r.page.title||'(not found)')}${evidence('Forms',r.page.form_count??0)}${evidence('Password fields',r.page.password_fields??0)}${evidence('External form actions',(r.page.external_form_actions||[]).length)}${evidence('Iframes',r.page.iframe_count??0)}${evidence('Hidden iframes',r.page.hidden_iframes??0)}${evidence('Links extracted',(r.page.links||[]).length)}</div>${(r.page.external_form_actions||[]).length?`<h4 style="margin-top:18px">Form destinations</h4>${(r.page.external_form_actions||[]).map(x=>`<p class="report-target">${esc(x)}</p>`).join('')}`:''}</section>`;}
    if(r.live_inspection){const v=r.live_inspection;details+=`<section class="report-panel"><h4>Live page inspection</h4><div class="evidence-list">${evidence('Status',v.status||'completed')}${evidence('Pages inspected',(v.pages||[]).length)}${evidence('Redirects',(v.redirect_chain||[]).length)}${evidence('Blocked / errors',(v.errors||[]).length)}${evidence('TLS certificate accepted',v.tls_validated?'At least one HTTPS response':'Not established')}</div>${(v.pages||[]).map(p=>`<div class="signal-item"><div class="signal-top"><b>${esc(p.title||p.url)}</b><span class="badge info">HTTP ${esc(p.status??'—')}</span></div><p class="report-target">${esc(p.url)}</p><p>${(p.links||[]).length} same-origin page links · ${(p.external_links||[]).length} external links · ${(p.external_resources||[]).length} external resources · ${(p.password_fields||0)} password fields · ${(p.form_actions||[]).length} form action(s)</p>${(p.findings||[]).map(f=>`<p>• ${esc(f)}</p>`).join('')}<details class="page-evidence"><summary>Open response details</summary><div class="evidence-list">${evidence('Content type',p.content_type||'Not supplied')}${evidence('Redirect path',(p.redirect_chain||[]).join(' → ')||'—')}${Object.entries(p.headers||{}).map(([k,v])=>evidence(k,v)).join('')||evidence('Observed headers','None captured')}</div>${(p.form_actions||[]).length?`<h4>Form actions</h4>${p.form_actions.map(x=>`<p class="report-target">${esc(x)}</p>`).join('')}`:''}${(p.external_form_action_urls||[]).length?`<h4>External form destinations</h4>${p.external_form_action_urls.map(x=>`<p class="report-target">${esc(x)}</p>`).join('')}`:''}${(p.frame_sources||[]).length?`<h4>Iframe sources</h4>${p.frame_sources.map(x=>`<p class="report-target">${esc(x)}</p>`).join('')}`:''}${(p.external_links||[]).length?`<h4>External links (not fetched)</h4>${p.external_links.slice(0,80).map(x=>`<p class="report-target">${esc(x)}</p>`).join('')}`:''}${(p.resources||[]).length?`<h4>HTML resources (listed, not fetched)</h4>${p.resources.slice(0,80).map(x=>`<p class="report-target">${esc(x)}</p>`).join('')}`:''}${(p.external_resources||[]).length?`<h4>External resources (not fetched)</h4>${p.external_resources.slice(0,100).map(x=>`<p class="report-target">${esc(x)}</p>`).join('')}`:''}</details></div>`).join('')}${(v.errors||[]).length?`<div class="no-signals"><b>Fetch notes</b>${v.errors.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}</section>`;}
    if(r.imported_report){const ir=r.imported_report;details+=`<section class="report-panel"><h4>Imported report details</h4><div class="evidence-list">${evidence('Filename',ir.filename||'—')}${evidence('Format',ir.format||'JSON')}${evidence('Original verdict',ir.source_verdict||'Not identified')}${evidence('Original score',Number.isFinite(ir.source_risk_score)?`${ir.source_risk_score}/100`:'Not identified')}${evidence('Original report ID',ir.source_id||'Not identified')}${evidence('Top-level keys',(ir.keys||[]).join(', ')||'—')}${evidence('URLs extracted',(ir.url_reports||[]).length)}</div>${(ir.url_reports||[]).length?`<h4 style="margin-top:18px">URLs extracted from report</h4><div class="signal-list">${ir.url_reports.map(u=>`<div class="signal-item"><div class="signal-top"><b>${esc(u.input)}</b>${badge(u.verdict)}</div><p>${esc(u.hostname||'')} · ${Number.isFinite(u.risk_score)?u.risk_score+'/100':'Could not parse'}</p></div>`).join('')}</div>`:''}</section>`;}
    if(r.external_reputation) details += renderExternalReputation(r.external_reputation);
    if(r.whois_lookup && !r.external_reputation) details += renderWhoisLookup(r.whois_lookup);
    if(r.technical) details += renderTechnicalMetadata(r.technical);
    if(Array.isArray(r.investigation_modules)) details += renderModuleStatus(r.investigation_modules, r.coverage_summary || {});
    const rec=r.recommendation||'Treat the result as unverified and confirm through approved security tools.';const limits=(r.limitations||['Heuristic analysis can miss new attacks and produce false positives.','A low score or INCONCLUSIVE result is not proof of safety.']);
    return `<div class="report-summary"><div><div class="report-heading">${badge(r.verdict)}<h3>${esc(r.hostname||r.input||'Investigation')}</h3></div><div class="report-target">${esc(reportTarget)}</div><div class="report-meta">${meta.map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><div class="report-score"><strong style="color:${score>=60?'var(--red)':score>=30?'var(--amber)':'var(--blue)'}">${score}</strong><span>${r.imported_report?'SOURCE-REPORTED SCORE / 100':r.type==='FULL URL INVESTIGATION'?'COMPOSITE TRIAGE SCORE / 100':'HEURISTIC RISK / 100'}</span><div class="scorebar"><span style="width:${score}%;background:${score>=60?'var(--red)':score>=30?'var(--amber)':'var(--blue)'}"></span></div></div></div><div class="report-grid"><section class="report-panel"><h4>Signals and evidence <span class="panel-hint">${signals.length} scored finding(s)</span></h4>${signals.length?`<div class="signal-list">${signals.map(s=>`<div class="signal-item"><div class="signal-top"><b>${esc(s.title)}</b><span class="signal-meta">+${s.points}</span></div><p>${esc(s.detail)}</p></div>`).join('')}</div>`:`<div class="no-signals">No scored signals were returned. Review the limitations and keep the target unverified.</div>`}<div class="recommendation" style="margin-top:13px"><b>ANALYST RECOMMENDATION</b>${esc(rec)}</div></section><section class="report-panel"><h4>Context and limits</h4><div class="evidence-list">${evidence('Verdict',r.verdict)}${evidence('Hostname',r.hostname||'Not extracted')}${evidence('Data source',r.coverage_summary?.external_reputation_requested?'Local heuristics + external provider evidence':'Local heuristics' + (r.technical?' + network metadata':''))}${evidence('External reputation',r.coverage_summary?.external_reputation_requested?(r.external_reputation?.status||'Requested; see provider evidence'):'Not requested')}${evidence('URL fetched',r.live_inspection && (r.live_inspection.pages||[]).length?'Yes — controlled backend inspection':'No / not requested')}</div><div class="limitations"><b>Interpret with care</b><ul>${limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></section>${details}</div>`;
  }

  function safeProviderLink(raw, allowedHost){try{const u=new URL(String(raw||''));return u.protocol==='https:'&&u.hostname===allowedHost&&!u.username&&!u.password?u.href:''}catch{return ''}}
  function safeHttpLink(raw){try{const u=new URL(String(raw||''));return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}}
  function renderExternalReputation(rep){
    const names={virustotal:'VirusTotal',google_webrisk:'Google Web Risk',urlscan:'URLScan.io',abuseipdb:'AbuseIPDB'};
    const providers=rep.providers||{};
    const cards=Object.entries(names).map(([key,label])=>{
      const p=providers[key]||{status:'unknown',summary:'No result returned.'};
      const status=String(p.status||'unknown').replace(/[^a-z_]/g,'');
      const details=[];
      if(key==='virustotal'){
        if(Number.isFinite(p.malicious))details.push(evidence('Malicious detections',p.malicious));
        if(Number.isFinite(p.suspicious))details.push(evidence('Suspicious detections',p.suspicious));
        if(Number.isFinite(p.engine_results))details.push(evidence('Reported engine results',p.engine_results));
        if(p.title)details.push(evidence('Last reported page title',p.title));if(p.last_final_url)details.push(evidence('Last final URL',p.last_final_url));if(p.last_http_response_code!=null)details.push(evidence('Last HTTP status',p.last_http_response_code));if(p.last_analysis_date)details.push(evidence('Last analysis time',formatUnix(p.last_analysis_date)));if(p.last_submission_date)details.push(evidence('Last submission time',formatUnix(p.last_submission_date)));if(p.times_submitted!=null)details.push(evidence('Times submitted',p.times_submitted));if(p.reputation!=null)details.push(evidence('Community reputation',p.reputation));if(p.total_votes)details.push(evidence('Community votes',Object.entries(p.total_votes).map(([k,v])=>`${k}: ${v}`).join(' · ')));if(p.categories&&Object.keys(p.categories).length)details.push(`<details class="page-evidence"><summary>Provider categories (${Object.keys(p.categories).length})</summary>${Object.entries(p.categories).slice(0,50).map(([k,v])=>`<p><b>${esc(k)}</b> · ${esc(v)}</p>`).join('')}</details>`);if(Array.isArray(p.tags)&&p.tags.length)details.push(evidence('Tags',p.tags.slice(0,30).join(', ')));

        if(Array.isArray(p.detections)&&p.detections.length)details.push(`<details class="page-evidence"><summary>All malicious/suspicious detections (${p.detections.length})</summary>${p.detections.slice(0,200).map(d=>`<p><b>${esc(d.engine)}</b> · ${esc(d.category)}${d.result?` · ${esc(d.result)}`:''}</p>`).join('')}${p.all_engine_results_truncated?'<p>Provider returned more engine records than the UI maximum.</p>':''}</details>`);
        if(Array.isArray(p.all_engine_results)&&p.all_engine_results.length)details.push(`<details class="page-evidence"><summary>All engine results (${p.all_engine_results.length})</summary><div class="engine-table-wrap"><table class="engine-table"><thead><tr><th>Engine</th><th>Category</th><th>Result</th><th>Version</th><th>Update</th></tr></thead><tbody>${p.all_engine_results.slice(0,200).map(d=>`<tr><td>${esc(d.engine)}</td><td>${esc(d.category)}</td><td>${esc(d.result||'—')}</td><td>${esc(d.engine_version||'—')}</td><td>${esc(d.engine_update||'—')}</td></tr>`).join('')}</tbody></table></div></details>`);
        if(p.analysis_url){const al=safeProviderLink(p.analysis_url,'www.virustotal.com');if(al)details.push(`<p><a href="${escAttr(al)}" target="_blank" rel="noopener noreferrer">Open VirusTotal analysis ↗</a></p>`)}
      } else if(key==='google_webrisk'){
        if(Array.isArray(p.threat_types)&&p.threat_types.length)details.push(evidence('Threat lists',p.threat_types.join(', ')));
        if(p.expire_time)details.push(evidence('Cache expiry',p.expire_time));
      } else if(key==='urlscan'){
        if(Number.isFinite(p.count))details.push(evidence('Historical matches (provider total)',p.count));if(Number.isFinite(p.count)&&p.count>(Array.isArray(p.results)?p.results.length:0))details.push(evidence('Historical records displayed',Array.isArray(p.results)?p.results.length:0));
        if(Array.isArray(p.results)&&p.results.length)details.push(`<div class="provider-results">${p.results.slice(0,10).map(x=>{const link=safeProviderLink(x.result_url,'urlscan.io');return `<p><b>${esc(x.title||x.url||x.scan_id||'Historical scan')}</b>${x.malicious?' · <strong>Malicious verdict reported</strong>':''}${x.overall_score!=null?` · score ${esc(x.overall_score)}`:''}${x.time?`<br><small>${esc(x.time)} · ${esc(x.visibility||'visibility not returned')}</small>`:''}${link?`<br><a href="${escAttr(link)}" target="_blank" rel="noopener noreferrer">Open historical result ↗</a>`:''}</p>`}).join('')}</div>`);
        const ns=p.new_scan||{};details.push(evidence('Fresh scan',ns.status||'not requested'));if(ns.summary)details.push(`<p>${esc(ns.summary)}</p>`);if(ns.visibility)details.push(evidence('Visibility',ns.visibility));if(ns.scan_id)details.push(evidence('Scan ID',ns.scan_id));if(ns.result?.title)details.push(evidence('Rendered title',ns.result.title));if(ns.result?.url)details.push(evidence('Scanned URL',ns.result.url));if(ns.result?.domain)details.push(evidence('Page domain',ns.result.domain));if(ns.result?.ip)details.push(evidence('Page IP',ns.result.ip));if(ns.result?.country)details.push(evidence('Country',ns.result.country));if(ns.result?.asn)details.push(evidence('ASN',ns.result.asn));if(ns.result?.server)details.push(evidence('Server header',ns.result.server));if(ns.result?.mime_type)details.push(evidence('MIME type',ns.result.mime_type));if(ns.result?.overall_malicious!==undefined)details.push(evidence('Remote overall verdict',ns.result.overall_malicious?'Malicious':'Not flagged malicious'));if(ns.result?.requests!=null)details.push(evidence('Network requests',ns.result.requests));if(ns.result?.data_length!=null)details.push(evidence('Transferred bytes',ns.result.data_length));if(Array.isArray(ns.result?.domains_observed)&&ns.result.domains_observed.length)details.push(`<details class="page-evidence"><summary>Observed domains (${ns.result.domains_observed.length})</summary>${ns.result.domains_observed.map(x=>`<p>${esc(x)}</p>`).join('')}</details>`);if(Array.isArray(ns.result?.ips_observed)&&ns.result.ips_observed.length)details.push(`<details class="page-evidence"><summary>Observed IPs (${ns.result.ips_observed.length})</summary>${ns.result.ips_observed.map(x=>`<p>${esc(x)}</p>`).join('')}</details>`);if(Array.isArray(ns.result?.trackers_observed)&&ns.result.trackers_observed.length)details.push(`<details class="page-evidence"><summary>Trackers observed (${ns.result.trackers_observed.length})</summary>${ns.result.trackers_observed.map(x=>`<p>${esc(x)}</p>`).join('')}</details>`);const newLink=safeProviderLink(ns.result_url||ns.result?.result_url,'urlscan.io');if(newLink)details.push(`<p><a href="${escAttr(newLink)}" target="_blank" rel="noopener noreferrer">Open fresh URLScan result ↗</a></p>`);
      } else if(key==='abuseipdb'){
        ['ip_address','abuse_confidence_score','total_reports','distinct_users','last_reported_at','country_code','country_name','isp','usage_type','domain','is_tor','is_whitelisted'].forEach(k=>{if(p[k]!==undefined&&p[k]!==null&&p[k]!=='')details.push(evidence(({ip_address:'Resolved public IP',abuse_confidence_score:'Abuse confidence / 100',total_reports:'Reports (90 days)',distinct_users:'Distinct reporters',last_reported_at:'Last reported',country_code:'Country code',country_name:'Country name',isp:'ISP',usage_type:'Usage type',domain:'Domain',is_tor:'Tor exit node',is_whitelisted:'IP whitelisted'})[k],p[k]))});
      }
      const linkHost={virustotal:'www.virustotal.com',abuseipdb:'www.abuseipdb.com'}[key];
      const link=linkHost?safeProviderLink(p.report_url,linkHost):'';
      return `<article class="provider-card"><h5>${esc(label)}</h5><span class="provider-status ${status}">${esc(p.status||'unknown').replaceAll('_',' ')}</span><p>${esc(p.summary||'No summary available.')}</p>${details.length?`<div class="provider-results">${details.join('')}</div>`:''}${link?`<p><a href="${escAttr(link)}" target="_blank" rel="noopener noreferrer">Open provider report ↗</a></p>`:''}</article>`;
    }).join('');
    const shared=Object.entries(rep.external_data_shared||{}).map(([k,v])=>evidence(k.replaceAll('_',' '),v)).join('');
    const limits=(rep.limitations||[]).map(x=>`<li>${esc(x)}</li>`).join('');
    return `<section class="report-panel"><h4>External threat-intelligence results</h4><p>Provider results are independent evidence and do not automatically overwrite the local heuristic score.</p><div class="reputation-provider-grid">${cards}</div>${rep.whois?renderWhoisLookup(rep.whois):''}<details class="page-evidence" style="margin-top:12px"><summary>Data sharing &amp; limitations</summary><div class="evidence-list">${shared}</div><ul>${limits}</ul></details></section>`;
  }
  function renderWhoisLookup(w){
    const fields=[['Registered domain / target',w.target||w.registered_name],['Registered name',w.registered_name],['Registrar',w.registrar],['RDAP handle',w.handle],['Object type',w.object_class_name],['Created',w.created_at],['Last updated',w.updated_at],['Expires',w.expires_at],['Nameservers',(w.nameservers||[]).join(', ')],['RDAP status',(w.statuses||[]).join(', ')],['DNSSEC delegation signed',w.dnssec_signed===true?'Yes':w.dnssec_signed===false?'No':'Not reported'],['Lookup type',w.lookup_type],['RDAP endpoint',w.rdap_url]];
    const body=fields.filter(([k,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>evidence(k,v)).join('');
    const events=Array.isArray(w.events)&&w.events.length?`<details class="page-evidence"><summary>RDAP event timeline (${w.events.length})</summary>${w.events.map(x=>`<p>${esc(x.action||'Event')} · ${esc(x.date||'Date unavailable')}</p>`).join('')}</details>`:'';
    const roles=Array.isArray(w.entity_roles)&&w.entity_roles.length?evidence('Published entity roles',w.entity_roles.join(', ')):'';
    const notices=Array.isArray(w.notices)&&w.notices.length?`<details class="page-evidence"><summary>Registry notices (${w.notices.length})</summary>${w.notices.map(n=>`<p><b>${esc(n.title||'Notice')}</b>${(n.description||[]).map(d=>`<br>${esc(d)}`).join('')}${(n.links||[]).map(l=>{const href=safeHttpLink(l.href);return href?`<br><a href="${escAttr(href)}" target="_blank" rel="noopener noreferrer">${esc(l.rel||'Notice link')} ↗</a>`:''}).join('')}</p>`).join('')}</details>`:'';
    const links=Array.isArray(w.links)&&w.links.length?`<details class="page-evidence"><summary>RDAP links (${w.links.length})</summary>${w.links.slice(0,30).map(l=>`<p>${esc(l.rel||'link')} · ${esc(l.type||'')}<br>${esc(l.href||'')}</p>`).join('')}</details>`:'';
    return `<section class="report-panel"><h4>WHOIS / RDAP registration lookup</h4><span class="provider-status ${String(w.status||'unknown').replace(/[^a-z_]/g,'')}">${esc(w.status||'unknown').replaceAll('_',' ')}</span><p>${esc(w.summary||'No registration summary available.')}</p>${body?`<div class="evidence-list">${body}${roles}</div>`:''}${events}${notices}${links}<p class="panel-hint">RDAP data may be redacted, incomplete, cached, or unavailable; registration metadata is not proof of trust.</p></section>`;
  }
  function renderTechnicalMetadata(technical){
    const d=technical?.dns||{}, t=technical?.tls||{}, ct=technical?.certificate_transparency||{}, records=d.records||{};
    const recordTypes=['A','AAAA','CNAME','MX','NS','TXT','CAA','SOA','DMARC_TXT'];
    const recordRows=recordTypes.map(k=>{const x=records[k];if(!x)return '';const vals=(x.records||[]).join(' | ')||x.message||x.status||'No records';return evidence(k,vals)}).join('');
    const dnsFields=[evidence('DNS status',d.status||'unknown'),evidence('Hostname',d.hostname||'—'),evidence('Registrable domain',d.registrable_domain||'—'),evidence('Resolver',d.resolver||'—'),evidence('IPv4 addresses',(d.address_summary?.ipv4||[]).join(', ')||'None reported'),evidence('IPv6 addresses',(d.address_summary?.ipv6||[]).join(', ')||'None reported'),evidence('Non-public DNS answer observed',d.address_summary?.non_public_answers_observed?'Yes — crawler will block it':'No')].join('');
    const spf=(d.email_auth_summary?.spf_records||[]).join(' | '), dmarc=(d.email_auth_summary?.dmarc_records||[]).join(' | ');
    const tlsFields=[evidence('TLS status',t.status||'unknown'),evidence('Certificate verified',t.certificate_verified===true?'Yes':t.certificate_verified===false?'No':'Not established'),evidence('Peer IP',t.peer_ip||'—'),evidence('TLS version',t.tls_version||'—'),evidence('Cipher',t.cipher||'—'),evidence('Subject',t.subject||'—'),evidence('Issuer',t.issuer||'—'),evidence('Valid from',t.valid_from||'—'),evidence('Valid until',t.valid_until||'—'),evidence('Days to expiry',t.days_until_expiry??'—'),evidence('Serial number',t.serial_number||'—'),evidence('SHA-256 fingerprint',t.sha256_fingerprint||'—')].join('');
    const ctEntries=(ct.entries||[]).slice(0,50);
    const ctRows=ctEntries.map(x=>`<tr><td>${esc(x.common_name||'—')}<details><summary>Names / SAN entries</summary><pre>${esc(x.name_value||x.common_name||'—')}</pre></details></td><td>${esc(x.issuer_name||'—')}</td><td>${esc(x.not_before||'—')}</td><td>${esc(x.not_after||'—')}</td><td>${x.id?`<a href="https://crt.sh/?id=${encodeURIComponent(x.id)}" target="_blank" rel="noopener noreferrer">${esc(x.id)} ↗</a>`:'—'}</td></tr>`).join('');
    const ctDetails=`<section class="report-panel"><h4>Certificate transparency history</h4><span class="provider-status ${String(ct.status||'unknown').replace(/[^a-z_]/g,'')}">${esc(ct.status||'unknown').replaceAll('_',' ')}</span><p>${esc(ct.summary||'CT history was not returned.')}</p>${ctEntries.length?`<div class="engine-table-wrap"><table class="engine-table"><thead><tr><th>Common name</th><th>Issuer</th><th>Not before</th><th>Not after</th><th>Log ID</th></tr></thead><tbody>${ctRows}</tbody></table></div>`:''}${ct.results_truncated?'<p class="panel-hint">More results exist than the displayed limit of 50; the full CT dataset was not downloaded.</p>':''}<p class="panel-hint">This is certificate issuance history from public CT logs, not a maliciousness verdict.</p></section>`;
    return `<section class="report-panel"><h4>Network metadata · DNS records</h4><p>${esc(d.message||'DNS metadata was not returned.')}</p><div class="evidence-list">${dnsFields}${recordRows}${spf?evidence('SPF record(s)',spf):''}${dmarc?evidence('DMARC record(s)',dmarc):''}</div>${(d.limitations||[]).length?`<ul class="metadata-notes">${d.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</section><section class="report-panel"><h4>TLS / certificate details</h4><span class="provider-status ${String(t.status||'unknown').replace(/[^a-z_]/g,'')}">${esc(t.status||'unknown').replaceAll('_',' ')}</span><p>${esc(t.message||'No TLS detail returned.')}</p><div class="evidence-list">${tlsFields}${(t.subject_alt_names||[]).length?evidence('Subject alternative names',(t.subject_alt_names||[]).join(', ')):''}</div>${(t.limitations||[]).length?`<ul class="metadata-notes">${t.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</section>${ctDetails}`;
  }
  function renderModuleStatus(modules,coverage){
    const rows=(modules||[]).map(m=>`<tr><td>${esc(m.name||'module')}</td><td><span class="provider-status ${String(m.status||'unknown').replace(/[^a-z_]/g,'')}">${esc(m.status||'unknown').replaceAll('_',' ')}</span></td><td>${esc(m.summary||'—')}</td></tr>`).join('');
    return `<section class="report-panel"><h4>Investigation coverage &amp; source status</h4><div class="evidence-list">${evidence('Pages requested',coverage.max_pages_requested??0)}${evidence('Pages inspected',coverage.pages_inspected??0)}${evidence('Providers configured',coverage.provider_count_configured??0)}${evidence('Network metadata consent',coverage.network_checks_confirmed?'Confirmed':'Not given')}${evidence('External reputation requested',coverage.external_reputation_requested?'Yes':'No')}${evidence('Sensitive URL blocked from provider lookup',coverage.sensitive_url_blocked_from_external_sharing?'Yes':'No')}</div><div class="engine-table-wrap"><table class="engine-table"><thead><tr><th>Module</th><th>Status</th><th>Evidence summary</th></tr></thead><tbody>${rows}</tbody></table></div><p class="panel-hint">A source marked unavailable, not configured, not requested, or rate limited did not produce a clean verdict. Review the status instead of treating missing data as safe.</p></section>`;
  }
  function isSensitiveExternalUrl(raw){try{const u=safeUrl(raw);for(const key of u.searchParams.keys()){if(/(?:token|access.?token|refresh.?token|secret|password|passwd|session|auth|authorization|reset|invite|verification|verify|otp|code|signature|api.?key|private.?key|jwt|email)/i.test(key))return true;}return false;}catch{return false}}
  function updateIntelButtons(){const base=!!getApiBase();$('#run-reputation').disabled=!base||!$('#external-sharing-confirm').checked;$('#run-whois').disabled=!base;$('#full-investigate').disabled=!base;}
  async function runFullInvestigation(){
    const target=$('#url-input').value.trim();
    if(!target){toast('Enter a URL/domain first.','warning');return;}
    const network=$('#network-checks-confirm').checked;
    const crawl=$('#live-crawl-confirm').checked;
    const external=$('#external-sharing-confirm').checked;
    const submitVT=$('#vt-submit-confirm').checked;
    const submitUrlscan=$('#urlscan-submit-confirm').checked;
    if(!network&&!external){toast('Select network metadata and/or external reputation consent to run a full investigation.','warning');return;}
    if(crawl&&!network){toast('Enable network metadata consent before you authorize page crawling.','warning');return;}
    if((submitVT||submitUrlscan)&&!external){toast('Fresh provider submissions also require external data-sharing consent.','warning');return;}
    if(external&&isSensitiveExternalUrl(target)){const msg='This URL appears to contain a reset/invite/session/token parameter. Remove the sensitive query and retry; do not send secret-bearing URLs to external providers.';$('#full-investigation-status').textContent=msg;toast(msg,'error');return;}
    const btn=$('#full-investigate');btn.disabled=true;btn.textContent='Investigating…';$('#full-investigation-status').textContent='Running selected modules. Some provider results may be unavailable, rate-limited, or not configured; each status will be shown in the report.';
    try{
      const report=await apiRequest('/api/v1/investigate',{
        url:target,
        max_pages:Number($('#full-max-pages').value)||5,
        confirm_network_checks:network,
        include_live_inspection:crawl,
        confirm_live_crawl:crawl,
        include_external_reputation:external,
        confirm_external_sharing:external,
        submit_virustotal_if_missing:submitVT,
        confirm_virustotal_submission:submitVT,
        submit_urlscan_private:submitUrlscan,
        confirm_urlscan_submission:submitUrlscan
      });
      showReport(report);
      const cov=report.coverage_summary||{};
      $('#full-investigation-status').textContent=`Investigation finished in ${report.elapsed_ms??'—'} ms · ${cov.pages_inspected??0} page(s) crawled · ${cov.provider_count_configured??0} provider(s) configured. Expand source status and missing modules in the report.`;
      toast('Full investigation returned. Review evidence, source statuses and coverage.');
    }catch(e){$('#full-investigation-status').textContent=e.message;toast(e.message,'error');}
    finally{btn.innerHTML='Run full investigation ↗';updateIntelButtons();}
  }
  async function runReputationLookup(){
    const target=$('#url-input').value.trim();if(!target){toast('Enter a URL/domain first.','warning');return;}
    if(!$('#external-sharing-confirm').checked){toast('Confirm external data sharing before running threat-intel lookups.','warning');return;}
    if(isSensitiveExternalUrl(target)){const msg='This URL appears to contain a reset/invite/session/token parameter. Remove the query string and retry to avoid sharing secrets with third parties.';$('#intel-status').textContent=msg;toast(msg,'error');return;}
    const btn=$('#run-reputation');btn.disabled=true;btn.textContent='Querying providers…';$('#intel-status').textContent='Contacting configured providers in parallel. This can take several seconds.';
    try{const submitVT=$('#vt-submit-confirm').checked;const submitUrlscan=$('#urlscan-submit-confirm').checked;const report=await apiRequest('/api/v1/reputation',{target,confirm_external_sharing:true,submit_virustotal_if_missing:submitVT,confirm_virustotal_submission:submitVT,submit_urlscan_private:submitUrlscan,confirm_urlscan_submission:submitUrlscan});if(currentReport&&currentReport.hostname===report.hostname&&currentReport.whois_lookup)report.whois_lookup=currentReport.whois_lookup;showReport(report);const configured=report.external_reputation?.configured_provider_count??0;$('#intel-status').textContent=`Lookup finished. ${configured} external provider(s) configured; open the report to review source-by-source evidence.`;toast('Threat-intelligence lookup finished. Review each provider result.');}
    catch(e){$('#intel-status').textContent=e.message;toast(e.message,'error');}
    finally{btn.textContent='Run threat-intel checks ↗';updateIntelButtons();}
  }
  async function runWhoisLookup(){
    const target=$('#url-input').value.trim();if(!target){toast('Enter a domain or URL first.','warning');return;}
    let host;try{host=hostOf(safeUrl(target));}catch(e){toast(e.message,'error');return;}
    const btn=$('#run-whois');btn.disabled=true;btn.textContent='Looking up…';$('#intel-status').textContent=`Looking up registration metadata for ${host}; no page is fetched.`;
    try{const result=await apiRequest('/api/v1/whois',{target:host});let report=(currentReport&&currentReport.hostname===host)?{...currentReport}:analyzeUrl(target);if(report.external_reputation)report.external_reputation.whois=result.whois;else report.whois_lookup=result.whois;report.type=report.external_reputation?'URL + THREAT INTEL + WHOIS':'URL + WHOIS';showReport(report);$('#intel-status').textContent=`WHOIS/RDAP lookup complete for ${host}.`;toast('WHOIS/RDAP lookup complete.');}
    catch(e){$('#intel-status').textContent=e.message;toast(e.message,'error');}
    finally{btn.textContent='WHOIS / RDAP lookup';updateIntelButtons();}
  }

  function evidence(label,value){return `<div class="evidence-row"><span>${esc(label)}</span><b>${esc(value)}</b></div>`}
  function toast(message, kind=''){const box=document.createElement('div');box.className=`toast ${kind}`;box.textContent=message;$('#toast-region').append(box);setTimeout(()=>box.remove(),4500)}
  function downloadJson(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'});downloadBlob(blob,`${name}.json`)}function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
  function getApiBase(){let v='';try{v=localStorage.getItem(API_KEY)||''}catch{}if(!v&&originLooksLocal&&/^https?:$/.test(location.protocol))v=location.origin;return v.replace(/\/+$/,'')}
  function setApiHint(){const base=getApiBase();$('#api-hint').textContent=base?`API configured: ${base}. Full investigation requires provider secrets, network metadata flags and bounded-crawl abuse controls on the backend.`:'Full online investigation is disabled until a PhishShield API base URL is configured in Settings.';$('#engine-status').textContent=base&&originLooksLocal?'LOCAL API CONNECTED':base?'LOCAL + REMOTE API':'LOCAL ENGINE READY';$('#stat-mode').textContent=base?'HYBRID':'LOCAL';$('#stat-mode-sub').textContent=base?'Local rules + configured metadata/reputation API':'No remote services connected';if($('#intel-status'))$('#intel-status').textContent=base?'Use Run full investigation to combine DNS/TLS/CT, RDAP, provider results, and bounded page crawling according to consent.':'Configure your PhishShield API in Settings. Never paste provider keys into this website.';updateIntelButtons()}
  async function apiRequest(path, body){const base=getApiBase();if(!base)throw new Error('No API is configured. Open Settings and add your deployed PhishShield API base URL.');let response;try{response=await fetch(`${base}${path}`,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,mode:'cors',credentials:'omit',redirect:'error',cache:'no-store'});}catch(e){throw new Error('Cannot reach the API. Check the API URL, HTTPS, CORS allowlist and backend health.');}const ct=response.headers.get('content-type')||'';let result;try{result=ct.includes('json')?await response.json():await response.text()}catch{result=null}if(!response.ok)throw new Error((result&&result.detail)||`API returned HTTP ${response.status}.`);return result;}
  function activateTab(id){$$('.tab').forEach(t=>{const on=t.dataset.tab===id;t.classList.toggle('active',on);t.setAttribute('aria-selected',String(on))});$$('.tab-panel').forEach(p=>{const on=p.id===id;p.classList.toggle('active',on);p.hidden=!on})}
  function analyzeImportedJson(text, filename) {
    let parsed; try { parsed = JSON.parse(text); } catch { return analyzeEmail(text, filename); }
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return analyzeEmail(text, filename);
    const rawUrls = extractUrls(JSON.stringify(parsed));
    const urlReports = rawUrls.slice(0,50).map(input => { try { const r=analyzeUrl(input); return {input,hostname:r.hostname,verdict:r.verdict,risk_score:r.risk_score,signals:r.signals}; } catch { return {input,hostname:'',verdict:'UNPARSEABLE',risk_score:null,signals:[]}; } });
    const knownReport = Number.isFinite(parsed.risk_score) && typeof parsed.verdict === 'string' && Array.isArray(parsed.signals);
    if (knownReport) {
      const sourceScore = parsed.risk_score;
      const score = Math.max(0, Math.min(100, sourceScore));
      const safeSignals = parsed.signals.filter(x => x && typeof x === 'object').slice(0,100).map((x,i) => ({id:String(x.id ?? `imported-${i}`).slice(0,100),title:String(x.title ?? 'Imported finding').slice(0,500),detail:String(x.detail ?? '').slice(0,3000),points:Math.max(0,Math.min(100,Number.isFinite(x.points)?x.points:0)),severity:['info','low','medium','high'].includes(x.severity)?x.severity:'info'}));
      const r = {id:makeId(),created_at:new Date().toISOString(),type:'IMPORTED REPORT',input:String(parsed.input||parsed.normalized_url||filename).slice(0,2000),hostname:typeof parsed.hostname==='string'?parsed.hostname.slice(0,300):'',normalized_url:typeof parsed.normalized_url==='string'?parsed.normalized_url.slice(0,4096):'',verdict:String(parsed.verdict).slice(0,80),risk_score:score,risk_level:score>=60?'high':score>=30?'medium':'low',signals:safeSignals,recommendation:typeof parsed.recommendation==='string'?parsed.recommendation.slice(0,3000):'This report was imported and is not independently verified.',limitations:[...(Array.isArray(parsed.limitations)?parsed.limitations.filter(x=>typeof x==='string').slice(0,30).map(x=>x.slice(0,1000)):[]),'This is an imported report. Its contents, score, verdict and timestamps have not been independently authenticated.'],imported_report:{filename,format:'JSON',source_verdict:String(parsed.verdict).slice(0,80),source_risk_score:sourceScore,source_id:typeof parsed.id==='string'?parsed.id.slice(0,120):'',source_created_at:typeof parsed.created_at==='string'?parsed.created_at.slice(0,120):'',keys:Object.keys(parsed).slice(0,80),url_reports:urlReports}};
      return r;
    }
    const maxScore = urlReports.reduce((m,u)=>Number.isFinite(u.risk_score)?Math.max(m,u.risk_score):m,0);
    const scoreSignals=[]; const seen=new Set();
    for(const u of urlReports){for(const f of (u.signals||[])){if(f.points>0&&!seen.has(f.id)){seen.add(f.id);scoreSignals.push({...f,detail:`Observed in extracted URL ${u.input}: ${f.detail}`})}}}
    if(!scoreSignals.length)scoreSignals.push({id:'json-no-signal',title:'No scored URL indicators extracted',detail:'This JSON file does not match the PhishShield report schema. URL heuristics found no scored indicators; other JSON fields were not interpreted as a verdict.',points:0,severity:'info'});
    return {id:makeId(),created_at:new Date().toISOString(),type:'IMPORTED JSON REPORT',input:filename,verdict:maxScore>=60?'HIGH RISK':maxScore>=30?'SUSPICIOUS':'INCONCLUSIVE',risk_score:maxScore,risk_level:maxScore>=60?'high':maxScore>=30?'medium':'low',signals:scoreSignals,signal_count:scoreSignals.length,recommendation:'This is an imported JSON document. Verify its origin and meaning before relying on any field; only extracted URLs were heuristically triaged by PhishShield.',imported_report:{filename,format:'JSON',keys:Object.keys(parsed).slice(0,80),source_verdict:typeof parsed.verdict==='string'?parsed.verdict:'',source_risk_score:Number.isFinite(parsed.risk_score)?parsed.risk_score:null,source_id:typeof parsed.id==='string'?parsed.id:'',url_reports:urlReports},limitations:['The file content is untrusted and has not been authenticated.','For a non-PhishShield JSON file, only URLs extracted from serialized JSON were triaged; other fields are not interpreted as a verdict.','A low score or INCONCLUSIVE verdict is not proof of safety.']};
  }
  async function handleFile(file){
    if(!file)return;
    if(file.size>MAX_FILE){toast('File exceeds the 2 MB limit.','error');return;}
    const ext=(file.name.split('.').pop()||'').toLowerCase();
    if(!['eml','txt','html','htm','log','json','csv','md'].includes(ext)){toast('Unsupported file type. Choose EML, TXT, HTML, JSON, CSV or MD.','error');return;}
    try{
      const text=await file.text();
      if(ext==='html'||ext==='htm'){
        activateTab('file-panel');$('#file-loaded').hidden=false;$('#file-loaded').textContent=`Loaded ${file.name} · ${file.size.toLocaleString()} bytes. HTML is analyzed as inert text.`;$('#file-loaded').dataset.text=text;$('#file-loaded').dataset.filename=file.name;
        showReport(analyzeFileText(text,file.name));toast('HTML file analyzed locally.');
      }else if(ext==='json'){
        activateTab('file-panel');$('#file-loaded').hidden=false;$('#file-loaded').textContent=`Loaded ${file.name} · ${file.size.toLocaleString()} bytes. JSON report/data is parsed locally.`;$('#file-loaded').dataset.text=text;$('#file-loaded').dataset.filename=file.name;
        showReport(analyzeImportedJson(text,file.name));toast('JSON report/data analyzed locally.');
      }else{
        activateTab('email-panel');$('#email-input').value=text;$('#email-char').textContent=`${text.length.toLocaleString()} / 1 MB`;$('#email-input').dataset.filename=file.name;
        try{showReport(analyzeEmail(text,file.name));toast(`Loaded and analyzed ${file.name} locally.`);}catch(e){toast(e.message,'error')}
      }
    }catch{toast('Could not read this file as text.','error')}
  }
  function scanUrl(raw){try{const report=analyzeUrl(raw);showReport(report);toast('URL triage complete. The URL was not opened.');}catch(e){toast(e.message,'error')}}
  function scanEmail(){try{const report=analyzeEmail($('#email-input').value,$('#email-input').dataset.filename||'pasted-message');showReport(report);toast('Email analysis complete. Content stayed in your browser.');}catch(e){toast(e.message,'error')}}
  async function inspectPage(){const target=$('#inspect-url').value.trim();if(!target){toast('Enter a public URL to inspect.','warning');return;}const btn=$('#inspect-page');btn.disabled=true;btn.textContent='Inspecting…';try{const report=await apiRequest('/api/v1/inspect',{url:target,max_pages:Number($('#max-pages').value)||3});const merged={...report,type:'LIVE INSPECTION',live_inspection:report.inspection||report};if(merged.risk_score==null){const pages=merged.live_inspection.pages||[];const sig=[];const add=(id,title,detail,points,severity='medium')=>sig.push({id,title,detail,points,severity});for(const p of pages){(p.findings||[]).forEach((f,i)=>add(`${p.url}-${i}`,f,f,10,'medium'));if(p.status>=400)add('http-error','Page returned HTTP error',`${p.url} returned HTTP ${p.status}.`,4,'low')}const score=Math.min(100,sig.reduce((a,s)=>a+s.points,0));merged.signals=sig;merged.risk_score=score;merged.verdict=score>=60?'HIGH RISK':score>=30?'SUSPICIOUS':'INCONCLUSIVE';merged.recommendation='Use the page findings as a lead for review. This bounded fetch does not simulate a browser, log in, or inspect dynamic behavior.';merged.limitations=['Only a bounded number of pages are fetched. JavaScript is not executed.','This is not a malware sandbox or a definitive phishing verdict.','A low score is not proof of safety.'];}showReport(merged);toast('Live inspection complete. Review pages, findings and fetch errors.');}catch(e){toast(e.message,'error');}finally{btn.disabled=false;btn.innerHTML='Inspect page <span>↗</span>';}}
  function scanBatch(){const lines=$('#batch-input').value.split(/[\r\n,]+/).map(x=>x.trim()).filter(Boolean);const uniq=[...new Set(lines)].slice(0,200);if(!uniq.length){toast('Paste one or more URLs first.','warning');return;}const results=uniq.map(u=>{try{return analyzeUrl(u)}catch(e){return {input:u,verdict:'UNPARSEABLE',risk_score:0,signals:[{title:'Could not parse URL',detail:e.message,points:0}]}}});const div=$('#batch-results');div.hidden=false;div.innerHTML=results.map(r=>`<div class="batch-result-row"><span class="batch-target">${esc(r.input)}</span>${badge(r.verdict)}<span class="batch-score">${r.risk_score}/100</span></div>`).join('');const csv=['target,verdict,risk_score,signals',...results.map(r=>`"${String(r.input).replaceAll('"','""')}","${r.verdict}",${r.risk_score},"${(r.signals||[]).map(s=>s.title).join('; ').replaceAll('"','""')}"`)].join('\n');$('#batch-count').textContent=`${uniq.length} URL${uniq.length===1?'':'S'} ANALYZED`;$('#batch-count').onclick=()=>downloadBlob(new Blob([csv],{type:'text/csv'}),'phishshield-batch.csv');$('#batch-count').style.cursor='pointer';results.forEach(r=>{if(r.id&&r.verdict!=='UNPARSEABLE')record(r)});toast(`${uniq.length} URL(s) analyzed locally. Click the count to export CSV.`);}
  function saveApi(){let v=$('#api-base-input').value.trim();if(v){try{const u=new URL(v);if(!['https:','http:'].includes(u.protocol)||u.username||u.password||u.pathname!=='/'||u.search||u.hash)throw new Error();v=u.origin;}catch{toast('Enter a valid API origin, without a path, query or credentials.','error');return;}}try{if(v)localStorage.setItem(API_KEY,v);else localStorage.removeItem(API_KEY)}catch{toast('Could not save settings in this browser.','error');return;}setApiHint();$('#settings-modal').hidden=true;toast(v?'API base URL saved in this browser.':'API connection removed.');}
