    $('#export-json').addEventListener('click',()=>{if(currentReport)downloadJson(currentReport,currentFilename)});$('#print-report').addEventListener('click',()=>window.print());$('#history-filter').addEventListener('input',renderHistory);$('#clear-history').addEventListener('click',()=>{if(confirm('Clear all locally stored PhishShield cases from this browser?')){saveHistory([]);renderHistory();updateStats();toast('Local case history cleared.')}});$('#export-history').addEventListener('click',()=>downloadJson(loadHistory(),'phishshield-history'));$('#load-demo').addEventListener('click',()=>{activateTab('url-panel');$('#url-input').value='https://secure-login-paypal.account-check.click/verify?continue=%2Fbilling';$('#url-char').textContent=`${$('#url-input').value.length} / 4096`;scanUrl($('#url-input').value)});
    ['#open-settings','#open-settings-side','#open-settings-footer'].forEach(s=>$(s).addEventListener('click',openSettings));$('#close-settings').addEventListener('click',()=>$('#settings-modal').hidden=true);$('#settings-modal').addEventListener('click',e=>{if(e.target===$('#settings-modal'))$('#settings-modal').hidden=true});$('#save-settings').addEventListener('click',saveApi);$('#remove-api').addEventListener('click',()=>{$('#api-base-input').value='';saveApi()});$('#test-api').addEventListener('click',async()=>{const base=$('#api-base-input').value.trim().replace(/\/+$/,'');if(!base){$('#api-test-status').textContent='Enter an API base URL first.';return}$('#api-test-status').textContent='Checking /health…';try{const r=await fetch(`${base}/health`,{mode:'cors',credentials:'omit',cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);const d=await r.json();const configured=Object.entries(d.providers_configured||{}).filter(([name,yes])=>yes&&name!=='whois_rdap').map(([name])=>({virustotal:'VirusTotal',urlscan:'URLScan.io',google_webrisk:'Google Web Risk',abuseipdb:'AbuseIPDB'}[name]||name));const features=d.features||{};const enabled=[features.network_metadata_enabled?'DNS/TLS + certificate transparency':'',features.reputation_lookup_enabled?'reputation':'',features.whois_enabled?'WHOIS/RDAP':'',features.live_inspection_enabled?'live inspection':''].filter(Boolean);$('#api-test-status').textContent=`Connected · ${d.version||'API'} · Enabled: ${enabled.join(', ')||'local API only'} · Keys: ${configured.join(', ')||'none configured'}`;$('#api-test-status').style.color='var(--mint)'}catch{$('#api-test-status').textContent='Connection failed. Verify HTTPS, URL, CORS origin and /health endpoint.';$('#api-test-status').style.color='var(--red)'}});$('#clear-local-data').addEventListener('click',()=>{if(confirm('Clear local case history and remove saved API connection from this browser?')){localStorage.removeItem(HISTORY_KEY);localStorage.removeItem(API_KEY);$('#settings-modal').hidden=true;renderHistory();updateStats();setApiHint();toast('Local data cleared.')}});
    $('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$$('.nav-item').forEach(a=>a.addEventListener('click',()=>{$$('.nav-item').forEach(n=>n.classList.remove('active'));a.classList.add('active');$('#crumb-current').textContent=a.dataset.nav.toUpperCase().replaceAll('-',' ');$('#sidebar').classList.remove('open');if(a.dataset.nav==='email')activateTab('email-panel');if(a.dataset.nav==='investigate')activateTab('url-panel')}));window.addEventListener('hashchange',()=>{$$('.nav-item').forEach(a=>a.classList.toggle('active',location.hash===`#${a.dataset.nav}`||(!location.hash&&a.dataset.nav==='overview')));if(location.hash==='#email')activateTab('email-panel')});if(location.hash==='#email')activateTab('email-panel');$('#result-output').addEventListener('click',e=>{const b=e.target.closest('[data-scan-url]');if(b){activateTab('url-panel');$('#url-input').value=b.dataset.scanUrl;scanUrl(b.dataset.scanUrl)}});
